require(['jquery'], function($) {
  'use strict';

  var fieldset = $('fieldset.docextra');
  if (fieldset.length === 0) {
    return;
  }
  var master = fieldset.find('select[name$="_showdocumenttabs"]');
  var tabFields = fieldset.find('select').not(master);

  /**
   * Set every tab field at once. The tabs built in the skin have a yes/no property of their own while the tabs
   * contributed to the docextra extension point store a '+<id>' / '-<id>' entry in a shared list property,
   * so the value to select is not the same.
   */
  var setAllTabs = function(shown) {
    tabFields.each(function() {
      var field = $(this);
      var value = field.hasClass('documentTabVisibility') ?
        field.find('option[value^="' + (shown ? '+' : '-') + '"]').val() : (shown ? '1' : '0');
      field.val(value).trigger('change');
    });
  };

  fieldset.find('[data-documenttabs-bulk]').on('click', function(event) {
    event.preventDefault();
    setAllTabs($(this).attr('data-documenttabs-bulk') === 'show');
  });

  // The per tab settings have no effect while the whole tab area is hidden. The fields are left enabled so that
  // saving the form keeps them, but the administrator is told that they are not applied.
  var updateHiddenNotice = function() {
    fieldset.find('.documentTabsHiddenNotice').toggleClass('hidden', master.val() !== '0');
  };
  master.on('change', updateHiddenNotice);
  updateHiddenNotice();
});
